#include "causal_conv1d_def.h"
#include "causal_conv1d_tiling_validation.h"

void CausalConv1dDef::InitTiling(
    const aclmdlAclnnContext* context,
    const std::vector<aclDataBuffer*>& inputs,
    const std::vector<aclDataBuffer*>& outputs) {
    // 使用 host 端 INT64 元数据 tensor
    auto metadata_tensor = host_metadata_int64;
    auto tiling_data = ParseTilingFromHostMeta(metadata_tensor);

    // 根据 INT64 元数据设置 tiling 参数
    tiling_data.batch_size = metadata_tensor.GetShape()[0];
    tiling_data.seq_len = metadata_tensor.GetShape()[1];
    tiling_data.kernel_size = metadata_tensor.GetShape()[2];

    SetTilingBuffer(tiling_data);
}

