#include "causal_conv1d_def.h"
#include "causal_conv1d_tiling_validation.h"

void CausalConv1dDef::InitTiling(
    const aclmdlAclnnContext* context,
    const std::vector<aclDataBuffer*>& inputs,
    const std::vector<aclDataBuffer*>& outputs) {
    // 已切换到 device tensor，移除 INT64 host 元数据
    // INT64 行已移除，直接使用 device tensor
    auto device_tensor = GetDeviceTensor(context, 0);
    auto tiling_data = ParseTilingFromDeviceTensor(device_tensor);

    tiling_data.batch_size = device_tensor.GetShape()[0];
    tiling_data.seq_len = device_tensor.GetShape()[1];
    tiling_data.kernel_size = device_tensor.GetShape()[2];

    SetTilingBuffer(tiling_data);
}

